package rules

import "testing"

// Cases ported from PHP-CS-Fixer's PowToExponentiationFixerTest (tests/Fixer/Alias), then
// invented ones (named "extra"/"analyzer"/...); every expected output is what
// PHP-CS-Fixer 3.95 produces for the input.
func TestPowToExponentiationPhpCsFixerCases(t *testing.T) {
	t.Parallel()
	aliasRunUpstreamCases(t, PowToExponentiation{}, []aliasUpstreamCase{
		{"Fix#0", nil, "<?php pow(1,2);", "<?php 1**2;"},
		{"Fix#1", nil, "<?php pow(1,2)?>", "<?php 1**2?>"},
		{"Fix#2", nil, "<?php pow(1.2,2.3);", "<?php 1.2**2.3;"},
		{"Fix#3", nil, "<?php echo pow(-2, 3);", "<?php echo (-2)** 3;"},
		{"Fix#4", nil, "<?php echo pow(-2, -3);", "<?php echo (-2)**( -3);"},
		{"Fix#5", nil, "<?php echo pow(-2, 1-3);", "<?php echo (-2)**( 1-3);"},
		{"Fix#6", nil, "<?php echo pow(-2, -1-3);", "<?php echo (-2)**( -1-3);"},
		{"Fix#7", nil, "<?php $a = pow(3, +2);", "<?php $a = 3** +2;"},
		{"Fix#8", nil, "<?php pow($a--,++$b);", "<?php $a--**++$b;"},
		{"Fix#9", nil, "<?php pow(1//\n                #\n                ,2/**/ /**  */);", "<?php 1//\n                #\n                **2/**/ /**  */;"},
		{"Fix#10", nil, "<?php pow/**/(a(3/**/,4),$pow);//pow(1,2);", "<?php /**/a(3/**/,4)**$pow;//pow(1,2);"},
		{"Fix#11", nil, "<?php \\a\\pow(5,6);pow(7,8)?>", "<?php \\a\\pow(5,6);7**8?>"},
		{"Fix#12", nil, "<?php pow(pow(9,10),pow(11,12));", "<?php (9**10)**(11**12);"},
		{"Fix#13", nil, "<?php pow(1 + 2, 3 * 4);", "<?php (1 + 2)**( 3 * 4);"},
		{"Fix#14", nil, "<?php pow($b = 4, 3);", "<?php ($b = 4)** 3;"},
		{"Fix#15", nil, "<?php \\pow(13,14);", "<?php 13**14;"},
		{"Fix#16", nil, "<?php $a = 15 + \\pow(\\pow(16, 17), 18);", "<?php $a = 15 + (16** 17)** 18;"},
		{"Fix#17", nil, "<?php $a = pow($b, $c($d + 1));", "<?php $a = $b** $c($d + 1);"},
		{"Fix#18", nil, "<?php $a = pow(($a+$b), ($c-$d));", "<?php $a = ($a+$b)** ($c-$d);"},
		{"Fix#19", nil, "<?php $a = pow(2, '1'.'2'). 2;", "<?php $a = 2**( '1'.'2'). 2;"},
		{"Fix#20", nil, "<?php pow(A::B, 2);pow(\\A\\B\\C::B, 2);", "<?php A::B** 2;\\A\\B\\C::B** 2;"},
		{"Fix#21", nil, "<?php pow($obj->{$bar}, $obj->{$foo});", "<?php $obj->{$bar}** $obj->{$foo};"},
		{"Fix#22", nil, "<?php echo pow(${$bar}, ${$foo});", "<?php echo ${$bar}** ${$foo};"},
		{"Fix#23", nil, "<?php echo pow($a[2^3+1]->test(1,2), $b[2+$c]);", "<?php echo $a[2^3+1]->test(1,2)** $b[2+$c];"},
		{"Fix#24", nil, "<?php pow((int)\"2\",(float)\"3.0\");", "<?php (int)\"2\"**(float)\"3.0\";"},
		{"Fix#25", nil, "<?php pow(namespace\\Foo::BAR, 2);", "<?php namespace\\Foo::BAR** 2;"},
		{"Fix#26", nil, "<?php pow(-1, pow(-2, pow(-3, pow(-4, pow(-5, pow(-6, pow(-7, pow(-8, pow(-9, 3)))))))));", "<?php (-1)**( (-2)**( (-3)**( (-4)**( (-5)**( (-6)**( (-7)**( (-8)**( (-9)** 3))))))));"},
		{"Fix#27", nil, "<?php\n                    $z = pow(1,2);\n                    $a = \\pow(1, \\poW(2, \\pOw(3, \\pOW(4, \\Pow(5, \\PoW(6, \\POw(7, \\POW(8, \\pow(9, 3)))))))));\n                    $b = \\pow(1, \\pow(2, \\pow(3, \\pow(4, \\pow(5, \\pow(6, \\pow(7, \\pow(8, \\pow(9, 3)))))))));\n                    $d = pow(1,2);\n                ", "<?php\n                    $z = 1**2;\n                    $a = 1**( 2**( 3**( 4**( 5**( 6**( 7**( 8**( 9** 3))))))));\n                    $b = 1**( 2**( 3**( 4**( 5**( 6**( 7**( 8**( 9** 3))))))));\n                    $d = 1**2;\n                "},
		{"Fix#28", nil, "<?php $b = pow(3, __LINE__);", "<?php $b = 3** __LINE__;"},
		{"Fix#29", nil, "<?php\n                    pow($a-$b,\n                    pow($a-$b,\n                    pow($a-$b,\n                    pow($a-$b,\n                    pow($a-$b,$a-$b)\n                ))));", "<?php\n                    ($a-$b)**(\n                    ($a-$b)**(\n                    ($a-$b)**(\n                    ($a-$b)**(\n                    ($a-$b)**($a-$b)\n                ))));"},
		{"Fix#30", nil, "<?php pow(-1, pow($a, pow(1,2,3, pow($a-3, 4))));", "<?php (-1)**( $a** pow(1,2,3, ($a-3)** 4));"},
		{"Fix#31", nil, "<?php pow(1,2)    /**/ ?>", "<?php 1**2    /**/ ?>"},
		{"Fix#32", nil, "<?php pow($$a, $$b);", "<?php ($$a)**( $$b);"},
		{"Fix#33", nil, "<?php pow([1, 2, 3, 4][$x], 2);", "<?php [1, 2, 3, 4][$x]** 2;"},
		{"Fix#34", nil, "<?php echo pow(+$a, 2);", "<?php echo +$a** 2;"},
		{"Fix#35", nil, "<?php\n                interface Test\n                {\n                    public function pow($a, $b);\n                }", "<?php\n                interface Test\n                {\n                    public function pow($a, $b);\n                }"},
		{"Fix#36", nil, "<?php\n                interface Test\n                {\n                    public function &pow($a, $b);\n                }", "<?php\n                interface Test\n                {\n                    public function &pow($a, $b);\n                }"},
		{"Fix#37", nil, "<?php echo pow($a[1], $b[2+5]);", "<?php echo $a[1]** $b[2+5];"},
		{"Fix#38", nil, "<?php pow($b, ...$a);", "<?php pow($b, ...$a);"},
		{"Fix#39", nil, "<?php echo pow(+$a, 2,);", "<?php echo +$a** 2;"},
		{"Fix#40", nil, "<?php echo pow(+$a, 2/*1*/,/*2*/);", "<?php echo +$a** 2/*1*//*2*/;"},
		{"Fix#41", nil, "<?php\n$a = pow(\n    1,\n    2,\n);\n", "<?php\n$a = \n    1**\n    2\n;\n"},
		{"Fix#42", nil, "<?php echo pow(10_0, 2);", "<?php echo 10_0** 2;"},
		{"Fix#43", nil, "<?php pow(); ++$a;++$a;++$a;++$a;++$a;++$a;// pow(1,2);", "<?php pow(); ++$a;++$a;++$a;++$a;++$a;++$a;// pow(1,2);"},
		{"Fix#44", nil, "<?php pow(5); ++$a;++$a;++$a;++$a;++$a;++$a;# pow(1,2);", "<?php pow(5); ++$a;++$a;++$a;++$a;++$a;++$a;# pow(1,2);"},
		{"Fix#45", nil, "<?php pow(5,1,1); ++$a;++$a;++$a;++$a;++$a;++$a;/* pow(1,2); */", "<?php pow(5,1,1); ++$a;++$a;++$a;++$a;++$a;++$a;/* pow(1,2); */"},
		{"Fix#46", nil, "<?php \\a\\pow(4,3); ++$a;++$a;++$a;++$a;++$a;++$a;/** pow(1,2); */", "<?php \\a\\pow(4,3); ++$a;++$a;++$a;++$a;++$a;++$a;/** pow(1,2); */"},
		{"Fix80#47", nil, "<?php echo pow($a[2^3+1]?->test(1,2), $b[2+$c]);", "<?php echo $a[2^3+1]?->test(1,2)** $b[2+$c];"},
		{"extra #1", nil, "<?php\nnamespace Acme;\n\nuse function Other\\pow;\n\n$x = pow($a, 2);", "<?php\nnamespace Acme;\n\nuse function Other\\pow;\n\n$x = pow($a, 2);"},
		{"extra #2", nil, "<?php\nnamespace Acme;\n\nfunction pow($a, $b) {}\n\n$x = pow($a, 2);\n$y = \\pow($a, 2);", "<?php\nnamespace Acme;\n\nfunction pow($a, $b) {}\n\n$x = pow($a, 2);\n$y = $a** 2;"},
		{"extra #3", nil, "<?php\n$x = pow((string) $a, 2);\n$x = pow((bool) $a, 2);\n$x = pow(( float )$a, (integer) $b);\n$x = pow(\"$a\", 2);\n$x = pow(\"{$a}\", 2);\n$x = pow('a', \"b\");\n$x = pow(__FILE__, __LINE__);\n$x = pow(static::X, self::Y);\n$x = pow(new Foo(), 2);\n$x = pow(fn() => 1, 2);\n$x = pow($a ?? 1, $b ?: 2);", "<?php\n$x = ((string) $a)** 2;\n$x = ((bool) $a)** 2;\n$x = ( float )$a** (integer) $b;\n$x = (\"$a\")** 2;\n$x = (\"{$a}\")** 2;\n$x = 'a'** \"b\";\n$x = (__FILE__)** __LINE__;\n$x = (static::X)** self::Y;\n$x = (new Foo())** 2;\n$x = (fn() => 1)** 2;\n$x = ($a ?? 1)**( $b ?: 2);"},
		{"extra #4", nil, "<?php\n$x = pow(pow(-1, 2), pow(-3, 4));\n$x = pow(pow(1, -2), 3);\n$x = pow(1, pow(2, pow(-3, 4)));", "<?php\n$x = ((-1)** 2)**( (-3)** ));\n$x = (1**( -2))** 3;\n$x = 1**( 2**( (-3)** 4));"},
		{"extra #5", nil, "<?php\n$x = pow(...);\n$x = pow($a);\n$x = $obj->pow($a, 2) + Foo::pow($a, 2);", "<?php\n$x = pow(...);\n$x = pow($a);\n$x = $obj->pow($a, 2) + Foo::pow($a, 2);"},
		{"first-class callable #1", nil, "<?php $x = pow(foo([$a, $b->c]), bar(...));", "<?php $x = foo([$a, $b->c])** bar(...);"},
		{"first-class callable #2", nil, "<?php $x = pow(bar(...), 2);", "<?php $x = bar(...)** 2;"},
		{"first-class callable #3", nil, "<?php $x = pow(2, ...$args);", "<?php $x = pow(2, ...$args);"},
		{"exponent floats", nil, "<?php\n$a = pow(1e-3, 2);\n$b = pow(2, 1.5E+3);\n$c = pow(0x1E-3, 2);\n$d = pow(1e3, 2E-1_0);\n$e = pow(.5e+3, 1_0e-2);", "<?php\n$a = 1e-3** 2;\n$b = 2** 1.5E+3;\n$c = (0x1E-3)** 2;\n$d = 1e3** 2E-1_0;\n$e = .5e+3** 1_0e-2;"},
	})
}
